            auto filtered = TakeWhile(seq1, [&](ll i) -> bool {
                return countLength(0, i - 1) <= countLength(i, upb);
            });

            for (ll i : filtered) {
                auto seq0 = seq(0, i - 1);
                auto seqI = seq(i, getRight(i, countLength(0, i - 1)));

                auto selectA = Select(seq0, [&](ll a) -> char { return chars[a]; });
                auto selectB = Select(seqI, [&](ll b) -> char { return chars[b]; });

                if (SequenceEqual(selectA, selectB)) {
                    ll value = 1 + i + (n - i - countLength(0, i - 1));
